const results = [];

for (const item of $input.all()) {
  const raw = item.json.body ?? item.json;
  const text = raw.content?.[0]?.text || raw.choices?.[0]?.message?.content || '';

  const match = text.match(/\[[\s\S]*\]/);
  if (!match) continue;

  try {
    const topics = JSON.parse(match[0]);
    for (const t of topics) {
      results.push({ json: t });
    }
  } catch(e) {
    continue;
  }
}

return results;

